package studio.solocamera;
final class EditorStarterProjects {
 static final String[] NAMES={"Tutorial","Product review","Interview","Event highlight","Presentation"};
 static final String[][] SECTIONS={{"What you will learn","Step one","Step two","Step three","Recap & next step"},{"Meet the product","The problem it solves","Show it in use","Pros & limitations","Your verdict"},{"Meet the guest","The opening question","The main insight","A practical example","Final takeaway"},{"The opening scene","People & atmosphere","The main moment","Details & reactions","The closing scene"},{"Your presentation title","The problem","Your key ideas","A practical example","Summary & next steps"}};
 static EditorProject create(int kind,EditorCreatorStore store){EditorProject p=new EditorProject();p.name=NAMES[kind]+" starter";p.aspect=kind==3?1:2;p.allowMainGaps=false;for(int i=0;i<5;i++){EditorProject.Clip c=EditorTitlePresets.create(i==0?12:0,3000);c.text=SECTIONS[kind][i];c.designSubtitle="Edit this heading · add your footage on the video track";c.designEyebrow=NAMES[kind].toUpperCase(java.util.Locale.US);c.textY=i==0?0:-.50;store.applyBrand(c);c.text=SECTIONS[kind][i];EditorProject.Caption item=new EditorProject.Caption();item.style=c;item.type="Text";item.at=i*8000;item.end=item.at+3000;item.track=0;p.captions.add(item);}EditorProject.Caption end=new EditorProject.Caption();end.style=EditorTitlePresets.create(40,4000);store.applyBrand(end.style);end.at=36000;end.end=40000;end.track=0;p.captions.add(end);return p;}
}
